namespace CatalogSvc;

public class ProductCatalog
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, decimal> _prices = new(StringComparer.OrdinalIgnoreCase);
    // Reverse index: category → set of product codes
    private readonly Dictionary<string, HashSet<string>> _productsByCategory = new(StringComparer.OrdinalIgnoreCase);

    // Frozen snapshots for optimized reads
    private FrozenDictionary<string, string> _frozenCategories = FrozenDictionary<string, string>.Empty;
    private FrozenDictionary<string, decimal> _frozenPrices = FrozenDictionary<string, decimal>.Empty;
    private FrozenDictionary<string, FrozenSet<string>> _frozenProductsByCategory = FrozenDictionary<string, FrozenSet<string>>.Empty;
    private bool _isDirty;

    public void AddProduct(string code, string category, decimal price)
    {
        // Remove from previous category's reverse index if reassigning
        if (_categories.TryGetValue(code, out var oldCategory)
            && !oldCategory.Equals(category, StringComparison.OrdinalIgnoreCase)
            && _productsByCategory.TryGetValue(oldCategory, out var oldSet))
        {
            oldSet.Remove(code);
            if (oldSet.Count == 0)
                _productsByCategory.Remove(oldCategory);
        }

        _categories[code] = category;
        _prices[code] = price;

        if (!_productsByCategory.TryGetValue(category, out var set))
        {
            set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            _productsByCategory[category] = set;
        }
        set.Add(code);

        _isDirty = true;
    }

    /// <summary>
    /// Freezes the current catalog into read-optimized snapshots.
    /// Call after bulk loading is complete to maximize lookup throughput.
    /// </summary>
    public void Freeze()
    {
        if (!_isDirty) return;

        _frozenCategories = _categories.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenPrices = _prices.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenProductsByCategory = _productsByCategory.ToFrozenDictionary(
            kvp => kvp.Key,
            kvp => kvp.Value.ToFrozenSet(StringComparer.OrdinalIgnoreCase),
            StringComparer.OrdinalIgnoreCase);

        _isDirty = false;
    }

    public string? GetCategory(string code)
        => _frozenCategories.TryGetValue(code, out var cat) ? cat
         : _categories.TryGetValue(code, out cat) ? cat
         : null;

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        var prices = _isDirty ? (IReadOnlyDictionary<string, decimal>)_prices : _frozenPrices;
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (prices.TryGetValue(code, out var price))
                total += price;
        }
        return total;
    }

    /// <summary>
    /// Returns products in the given category in O(1) via the reverse index,
    /// replacing the previous O(n) full-scan approach.
    /// </summary>
    public List<string> GetProductsByCategory(string category)
    {
        if (_frozenProductsByCategory.TryGetValue(category, out var frozenSet))
            return new List<string>(frozenSet);

        if (_productsByCategory.TryGetValue(category, out var set))
            return new List<string>(set);

        return new List<string>();
    }
}

